PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL UNIQUE, issuer TEXT, subject TEXT, emailVerified INTEGER NOT NULL DEFAULT 0, createdAt INTEGER NOT NULL);
CREATE UNIQUE INDEX user_identity ON users(issuer, subject);
CREATE TABLE domains (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL UNIQUE, enabled INTEGER NOT NULL DEFAULT 1, createdAt INTEGER NOT NULL);
CREATE TABLE mailboxes (id TEXT PRIMARY KEY NOT NULL, domainId TEXT NOT NULL REFERENCES domains(id), address TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, createdAt INTEGER NOT NULL);
CREATE INDEX mailbox_domain ON mailboxes(domainId);
CREATE TABLE mailbox_grants (id TEXT PRIMARY KEY NOT NULL, userId TEXT NOT NULL REFERENCES users(id), mailboxId TEXT NOT NULL REFERENCES mailboxes(id), canRead INTEGER NOT NULL, canSend INTEGER NOT NULL);
CREATE UNIQUE INDEX grant_user_mailbox ON mailbox_grants(userId,mailboxId);
CREATE INDEX grant_mailbox ON mailbox_grants(mailboxId);
CREATE TABLE sessions (hash TEXT PRIMARY KEY NOT NULL, userId TEXT NOT NULL REFERENCES users(id), expiresAt INTEGER NOT NULL);
CREATE INDEX session_expiry ON sessions(expiresAt);
CREATE TABLE login_transactions (hash TEXT PRIMARY KEY NOT NULL, state TEXT NOT NULL, nonce TEXT NOT NULL, verifier TEXT NOT NULL, issuer TEXT NOT NULL, clientId TEXT NOT NULL, resource TEXT NOT NULL, origin TEXT NOT NULL, expiresAt INTEGER NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY NOT NULL, mailboxId TEXT NOT NULL REFERENCES mailboxes(id), dedupKey TEXT NOT NULL UNIQUE, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), messageId TEXT, inReplyTo TEXT, "references" TEXT NOT NULL, "from" TEXT NOT NULL, "to" TEXT NOT NULL, cc TEXT NOT NULL, bcc TEXT NOT NULL, subject TEXT NOT NULL, snippet TEXT NOT NULL, date INTEGER NOT NULL, bodyKey TEXT NOT NULL, rawKey TEXT, isRead INTEGER NOT NULL DEFAULT 0, isArchive INTEGER NOT NULL DEFAULT 0, isTrash INTEGER NOT NULL DEFAULT 0, hasAttachments INTEGER NOT NULL, sendState TEXT CHECK(sendState IN ('pending','accepted','failed','unknown')), errorCode TEXT, createdAt INTEGER NOT NULL);
CREATE INDEX message_mailbox_date ON messages(mailboxId,date,id);
CREATE INDEX message_reply ON messages(mailboxId,inReplyTo);
CREATE TABLE attachments (id TEXT PRIMARY KEY NOT NULL, mailboxId TEXT NOT NULL REFERENCES mailboxes(id), userId TEXT REFERENCES users(id), messageId TEXT REFERENCES messages(id), key TEXT NOT NULL, filename TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, contentId TEXT, disposition TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE INDEX attachment_message ON attachments(messageId);
CREATE INDEX upload_expiry ON attachments(createdAt);
CREATE TABLE send_requests (id TEXT PRIMARY KEY NOT NULL REFERENCES messages(id), userId TEXT NOT NULL REFERENCES users(id), key TEXT NOT NULL, fingerprint TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE UNIQUE INDEX send_idempotency ON send_requests(userId,key);
